import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

export function middleware(request: NextRequest) {
  // Log the request pathname to the console
  console.log(`Request Pathname: ${request.nextUrl.pathname}`)

  // Generate a unique ID for the request
  const requestId = crypto.randomUUID()

  // Create a response object
  const response = NextResponse.next()

  // Add the custom header "X-Request-Id" to the response
  response.headers.set('X-Request-Id', requestId)

  return response
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     */
    '/((?!_next/static|_next/image|favicon.ico).*)',
  ],
}

import { expect, test, vi } from 'vitest'
import { middleware } from './middleware'
import { NextRequest } from 'next/server'

test('middleware adds X-Request-Id header', () => {
  const request = new NextRequest('http://localhost:3000/')
  const response = middleware(request)

  const requestId = response.headers.get('X-Request-Id')
  expect(requestId).toBeDefined()
  expect(typeof requestId).toBe('string')
  expect(requestId?.length).toBeGreaterThan(0)
})

test('middleware logs pathname', () => {
  const consoleSpy = vi.spyOn(console, 'log')
  const request = new NextRequest('http://localhost:3000/test-path')
  middleware(request)

  expect(consoleSpy).toHaveBeenCalledWith('Request Pathname: /test-path')
})

